import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Button, Card, Checkbox, Dropdown, Form, Input, Label, Message} from 'semantic-ui-react';
import {useNavigate, useParams} from 'react-router-dom';
import {API, copy, getChannelModels, showError, showInfo, showSuccess, verifyJSON} from '../../helpers';
import {CHANNEL_OPTIONS, CHANNEL_MODEL_SUGGESTIONS} from '../../constants';
import {renderChannelTip} from '../../helpers/render';

const MODEL_MAPPING_EXAMPLE = {
  'gpt-3.5-turbo-0301': 'gpt-3.5-turbo',
  'gpt-4-0314': 'gpt-4',
  'gpt-4-32k-0314': 'gpt-4-32k',
};

function type2secretPrompt(type, t) {
  switch (type) {
    case 15:
      return t('channel.edit.key_prompts.zhipu');
    case 18:
      return t('channel.edit.key_prompts.spark');
    case 22:
      return t('channel.edit.key_prompts.fastgpt');
    case 23:
      return t('channel.edit.key_prompts.tencent');
    default:
      return t('channel.edit.key_prompts.default');
  }
}

const EditChannel = () => {
  const { t } = useTranslation();
  const params = useParams();
  const navigate = useNavigate();
  const channelId = params.id;
  const isEdit = channelId !== undefined;
  const [loading, setLoading] = useState(isEdit);
  const handleCancel = () => {
    navigate('/channel');
  };

  const originInputs = {
    name: '',
    type: 1,
    key: '',
    base_url: '',
    other: '',
    model_mapping: '',
    system_prompt: '',
    models: [],
    groups: ['default'],
  };
  const [batch, setBatch] = useState(false);
  const [inputs, setInputs] = useState(originInputs);
  const [originModelOptions, setOriginModelOptions] = useState([]);
  const [modelOptions, setModelOptions] = useState([]);
  const [groupOptions, setGroupOptions] = useState([]);
  const [basicModels, setBasicModels] = useState([]);
  const [fullModels, setFullModels] = useState([]);
  const [customModel, setCustomModel] = useState('');
  const [fetchedModels, setFetchedModels] = useState([]);
  const [fetchingModels, setFetchingModels] = useState(false);
  const [fetchError, setFetchError] = useState('');
  const [modelMappingPairs, setModelMappingPairs] = useState([]);
  const [mappingFrom, setMappingFrom] = useState('');
  const [mappingTo, setMappingTo] = useState('');
  const [config, setConfig] = useState({
    region: '',
    sk: '',
    ak: '',
    user_id: '',
    vertex_ai_project_id: '',
    vertex_ai_adc: '',
    // dyt-114: 上游协议出口开关（默认关闭，不改变既有行为）
    use_responses_api: false,
    use_interactions_api: false,
  });
  const handleInputChange = (e, { name, value }) => {
    setInputs((inputs) => ({ ...inputs, [name]: value }));
    if (name === 'type') {
      let localModels = getChannelModels(value);
      if (inputs.models.length === 0) {
        setInputs((inputs) => ({ ...inputs, models: localModels }));
      }
      setBasicModels(localModels);
    }
  };

  // dyt-54: 一键填入该渠道类型的推荐模型（来自 models.dev 最新数据）
  const fillSuggestedModels = () => {
    const suggestions = CHANNEL_MODEL_SUGGESTIONS[inputs.type];
    if (!suggestions || suggestions.length === 0) {
      showInfo('该渠道类型暂无推荐模型');
      return;
    }
    setInputs((inputs) => ({ ...inputs, models: suggestions }));
    showSuccess(`已填入 ${suggestions.length} 个推荐模型`);
  };

  const handleConfigChange = (e, { name, value }) => {
    setConfig((inputs) => ({ ...inputs, [name]: value }));
  };

  const loadChannel = async () => {
    try {
      let res = await API.get(`/api/channel/${channelId}`);
      const { success, message, data } = res.data;
      if (success) {
        if (data.models === '') {
          data.models = [];
        } else {
          data.models = data.models.split(',');
        }
        if (data.group === '') {
          data.groups = [];
        } else {
          data.groups = data.group.split(',');
        }
        if (data.model_mapping !== '') {
          // JSON.parse 加保护：脏数据不卡死页面
          try {
            data.model_mapping = JSON.stringify(
              JSON.parse(data.model_mapping),
              null,
              2
            );
          } catch (e) {
            showError('model_mapping 不是合法 JSON，已按原样显示');
          }
        }
        setInputs(data);
        if (data.config !== '') {
          try {
            setConfig(JSON.parse(data.config));
          } catch (e) {
            showError('config 不是合法 JSON，已忽略');
          }
        }
        setBasicModels(getChannelModels(data.type));
      } else {
        showError(message);
      }
    } catch (e) {
      showError('加载渠道失败：' + (e.response?.data?.message || e.message));
    }
    setLoading(false);
  };

  const fetchModels = async () => {
    try {
      let res = await API.get(`/api/channel/models`);
      let localModelOptions = res.data.data.map((model) => ({
        key: model.id,
        text: model.id,
        value: model.id,
      }));
      setOriginModelOptions(localModelOptions);
      setFullModels(res.data.data.map((model) => model.id));
    } catch (error) {
      showError(error.message);
    }
  };

  const fetchGroups = async () => {
    try {
      let res = await API.get(`/api/group/`);
      setGroupOptions(
        res.data.data.map((group) => ({
          key: group,
          text: group,
          value: group,
        }))
      );
    } catch (error) {
      showError(error.message);
    }
  };

  useEffect(() => {
    let localModelOptions = [...originModelOptions];
    inputs.models.forEach((model) => {
      if (!localModelOptions.find((option) => option.key === model)) {
        localModelOptions.push({
          key: model,
          text: model,
          value: model,
        });
      }
    });
    setModelOptions(localModelOptions);
  }, [originModelOptions, inputs.models]);

  // Parse model_mapping JSON into pairs for visual editor
  useEffect(() => {
    if (inputs.model_mapping && inputs.model_mapping.startsWith('{')) {
      try {
        const parsed = JSON.parse(inputs.model_mapping);
        const pairs = Object.entries(parsed).map(([from, to]) => ({from, to}));
        setModelMappingPairs(pairs);
      } catch (e) {
        // invalid JSON, ignore
      }
    } else {
      setModelMappingPairs([]);
    }
  }, [inputs.model_mapping]);

  const addModelMapping = (from, to) => {
    if (!from || !to) return;
    setModelMappingPairs(prev => {
      const next = [...prev, {from, to}];
      const obj = {};
      next.forEach(p => { obj[p.from] = p.to; });
      setInputs(i => ({ ...i, model_mapping: JSON.stringify(obj, null, 2) }));
      return next;
    });
  };

  const removeModelMapping = (index) => {
    setModelMappingPairs(prev => {
      const next = prev.filter((_, i) => i !== index);
      const obj = {};
      next.forEach(p => { obj[p.from] = p.to; });
      setInputs(i => ({ ...i, model_mapping: next.length > 0 ? JSON.stringify(obj, null, 2) : '' }));
      return next;
    });
  };

  useEffect(() => {
    if (isEdit) {
      loadChannel().then();
    } else {
      let localModels = getChannelModels(inputs.type);
      setBasicModels(localModels);
    }
    fetchModels().then();
    fetchGroups().then();
  }, []);

  const submit = async () => {
    let key = inputs.key;
    if (key === '') {
      if (config.ak !== '' && config.sk !== '' && config.region !== '') {
        key = `${config.ak}|${config.sk}|${config.region}`;
      } else if (
        config.region !== '' &&
        config.vertex_ai_project_id !== '' &&
        config.vertex_ai_adc !== ''
      ) {
        key = `${config.region}|${config.vertex_ai_project_id}|${config.vertex_ai_adc}`;
      }
    }
    if (!isEdit && (inputs.name === '' || key === '')) {
      showInfo(t('channel.edit.messages.name_required'));
      return;
    }
    if (inputs.type !== 43 && inputs.models.length === 0) {
      showInfo(t('channel.edit.messages.models_required'));
      return;
    }
    if (inputs.model_mapping !== '' && !verifyJSON(inputs.model_mapping)) {
      showInfo(t('channel.edit.messages.model_mapping_invalid'));
      return;
    }
    let localInputs = { ...inputs, key };
    if (localInputs.key === 'undefined|undefined|undefined') {
      localInputs.key = ''; // prevent potential bug
    }
    if (localInputs.base_url && localInputs.base_url.endsWith('/')) {
      localInputs.base_url = localInputs.base_url.slice(
        0,
        localInputs.base_url.length - 1
      );
    }
    if (localInputs.type === 3 && localInputs.other === '') {
      localInputs.other = '2024-03-01-preview';
    }
    let res;
    try {
      localInputs.models = localInputs.models.join(',');
      localInputs.group = localInputs.groups.join(',');
      localInputs.config = JSON.stringify(config);
      if (isEdit) {
        res = await API.put(`/api/channel/`, {
          ...localInputs,
          id: parseInt(channelId),
        });
      } else {
        res = await API.post(`/api/channel/`, localInputs);
      }
    } catch (e) {
      showError('请求失败：' + (e.response?.data?.message || e.message));
      return;
    }
    const { success, message } = res.data;
    if (success) {
      if (isEdit) {
        showSuccess(t('channel.edit.messages.update_success'));
      } else {
        showSuccess(t('channel.edit.messages.create_success'));
        setInputs(originInputs);
      }
    } else {
      showError(message);
    }
  };

  const handleFetchModels = async () => {
    setFetchingModels(true);
    setFetchError('');
    setFetchedModels([]);
    try {
      // Editing existing channel: use channel_id, backend reads full base_url+key from DB
      // New channel: pass base_url + key + type as before
      let res;
      if (isEdit && channelId) {
        res = await API.get(`/api/channel/fetch-models/${channelId}`);
      } else {
        const key = inputs.key || '';
        res = await API.post('/api/channel/fetch-models', {
          base_url: inputs.base_url || '',
          key: key,
          type: inputs.type
        });
      }
      const { success, message, data } = res.data;
      if (success && Array.isArray(data) && data.length > 0) {
        setFetchedModels(data);
        setFetchError('');
      } else if (success && Array.isArray(data) && data.length === 0) {
        setFetchedModels([]);
        setFetchError('获取到空模型列表');
      } else {
        setFetchedModels([]);
        setFetchError(message || '获取模型列表失败');
      }
    } catch (error) {
      setFetchedModels([]);
      setFetchError(error.message || '网络请求失败');
    }
    setFetchingModels(false);
  };

  const addCustomModel = () => {
    if (customModel.trim() === '') return;
    if (inputs.models.includes(customModel)) return;
    let localModels = [...inputs.models];
    localModels.push(customModel);
    let localModelOptions = [];
    localModelOptions.push({
      key: customModel,
      text: customModel,
      value: customModel,
    });
    setModelOptions((modelOptions) => {
      return [...modelOptions, ...localModelOptions];
    });
    setCustomModel('');
    handleInputChange(null, { name: 'models', value: localModels });
  };

  return (
    <div className='dashboard-container'>
      <Card fluid className='chart-card'>
        <Card.Content>
          <Card.Header className='header'>
            {isEdit
              ? t('channel.edit.title_edit')
              : t('channel.edit.title_create')}
          </Card.Header>
          <Form loading={loading} autoComplete='new-password'>
            <Form.Field>
              <Form.Select
                label={t('channel.edit.type')}
                name='type'
                required
                search
                options={CHANNEL_OPTIONS}
                value={inputs.type}
                onChange={handleInputChange}
              />
            </Form.Field>
            <Form.Field>
              <Form.Input
                label={t('channel.edit.name')}
                name='name'
                placeholder={t('channel.edit.name_placeholder')}
                onChange={handleInputChange}
                value={inputs.name}
                required
              />
            </Form.Field>
            <Form.Field>
              <Form.Dropdown
                label={t('channel.edit.group')}
                placeholder={t('channel.edit.group_placeholder')}
                name='groups'
                required
                fluid
                multiple
                selection
                allowAdditions
                additionLabel={t('channel.edit.group_addition')}
                onChange={handleInputChange}
                value={inputs.groups}
                autoComplete='new-password'
                options={groupOptions}
              />
            </Form.Field>
            {renderChannelTip(inputs.type)}

            {/* Azure OpenAI specific fields */}
            {inputs.type === 3 && (
              <>
                <Message>
                  注意，<strong>模型部署名称必须和模型名称保持一致</strong>
                  ，因为 One API 会把请求体中的 model
                  参数替换为你的部署名称（模型名称中的点会被剔除），
                  <a
                    target='_blank'
                    href='https://github.com/songquanpeng/one-api/issues/133?notification_referrer_id=NT_kwDOAmJSYrM2NjIwMzI3NDgyOjM5OTk4MDUw#issuecomment-1571602271'
                  >
                    图片演示
                  </a>
                  。
                </Message>
                <Form.Field>
                  <Form.Input
                    label='AZURE_OPENAI_ENDPOINT'
                    name='base_url'
                    placeholder='请输入 AZURE_OPENAI_ENDPOINT，例如：https://docs-test-001.openai.azure.com'
                    onChange={handleInputChange}
                    value={inputs.base_url}
                    autoComplete='new-password'
                  />
                </Form.Field>
                <Form.Field>
                  <Form.Input
                    label='默认 API 版本'
                    name='other'
                    placeholder='请输入默认 API 版本，例如：2024-03-01-preview，该配置可以被实际的请求查询参数所覆盖'
                    onChange={handleInputChange}
                    value={inputs.other}
                    autoComplete='new-password'
                  />
                </Form.Field>
              </>
            )}

            {/* Custom base URL field */}
            {inputs.type === 8 && (
              <Form.Field>
                <Form.Input
                    required
                    label={t('channel.edit.proxy_url')}
                    name='base_url'
                    placeholder={t('channel.edit.proxy_url_placeholder')}
                    onChange={handleInputChange}
                    value={inputs.base_url}
                    autoComplete='new-password'
                />
              </Form.Field>
            )}
            {inputs.type === 50 && (
                <Form.Field>
                  <Form.Input
                      required
                  label={t('channel.edit.base_url')}
                  name='base_url'
                  placeholder={t('channel.edit.base_url_placeholder')}
                  onChange={handleInputChange}
                  value={inputs.base_url}
                  autoComplete='new-password'
                />
              </Form.Field>
            )}

            {/* dyt-53: 需要自填 base_url 的新渠道（Xinference） */}
            {inputs.type === 54 && (
                <Form.Field>
                  <Form.Input
                      required
                  label={t('channel.edit.base_url')}
                  name='base_url'
                  placeholder={t('channel.edit.base_url_placeholder')}
                  onChange={handleInputChange}
                  value={inputs.base_url}
                  autoComplete='new-password'
                />
              </Form.Field>
            )}

            {inputs.type === 18 && (
              <Form.Field>
                <Form.Input
                  label={t('channel.edit.spark_version')}
                  name='other'
                  placeholder={t('channel.edit.spark_version_placeholder')}
                  onChange={handleInputChange}
                  value={inputs.other}
                  autoComplete='new-password'
                />
              </Form.Field>
            )}
            {inputs.type === 21 && (
              <Form.Field>
                <Form.Input
                  label={t('channel.edit.knowledge_id')}
                  name='other'
                  placeholder={t('channel.edit.knowledge_id_placeholder')}
                  onChange={handleInputChange}
                  value={inputs.other}
                  autoComplete='new-password'
                />
              </Form.Field>
            )}
            {inputs.type === 17 && (
              <Form.Field>
                <Form.Input
                  label={t('channel.edit.plugin_param')}
                  name='other'
                  placeholder={t('channel.edit.plugin_param_placeholder')}
                  onChange={handleInputChange}
                  value={inputs.other}
                  autoComplete='new-password'
                />
              </Form.Field>
            )}
            {inputs.type === 34 && (
              <Message>{t('channel.edit.coze_notice')}</Message>
            )}
            {inputs.type === 40 && (
              <Message>
                {t('channel.edit.douban_notice')}
                <a
                  target='_blank'
                  href='https://console.volcengine.com/ark/region:ark+cn-beijing/endpoint'
                >
                  {t('channel.edit.douban_notice_link')}
                </a>
                {t('channel.edit.douban_notice_2')}
              </Message>
            )}
            {inputs.type !== 43 && (
              <Form.Field>
                <Form.Dropdown
                  label={t('channel.edit.models')}
                  placeholder={t('channel.edit.models_placeholder')}
                  name='models'
                  required
                  fluid
                  multiple
                  search
                  onLabelClick={(e, { value }) => {
                    copy(value).then();
                  }}
                  selection
                  onChange={handleInputChange}
                  value={inputs.models}
                  autoComplete='new-password'
                  options={modelOptions}
                />
              </Form.Field>
            )}
            {inputs.type !== 43 && (
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px', alignItems: 'center', marginBottom: '12px' }}>
                <Button
                  type={'button'}
                  positive
                  onClick={fillSuggestedModels}
                >
                  填入推荐模型
                </Button>
                <Button
                  type={'button'}
                  onClick={() => {
                    handleInputChange(null, {
                      name: 'models',
                      value: basicModels,
                    });
                  }}
                >
                  {t('channel.edit.buttons.fill_models')}
                </Button>
                <Button
                  type={'button'}
                  onClick={() => {
                    handleInputChange(null, {
                      name: 'models',
                      value: fullModels,
                    });
                  }}
                >
                  {t('channel.edit.buttons.fill_all')}
                </Button>
                <Button
                  type={'button'}
                  onClick={() => {
                    handleInputChange(null, { name: 'models', value: [] });
                  }}
                >
                  {t('channel.edit.buttons.clear')}
                </Button>
                <Button
                  type={'button'}
                  loading={fetchingModels}
                  onClick={handleFetchModels}
                  style={{ marginLeft: '4px' }}
                >
                  {t('channel.edit.buttons.fetch_models')}
                </Button>
                <Input
                  action={
                    <Button type={'button'} onClick={addCustomModel}>
                      {t('channel.edit.buttons.add_custom')}
                    </Button>
                  }
                  style={{ flex: '1 1 100%', minWidth: '100%' }}
                  placeholder={t('channel.edit.buttons.custom_placeholder')}
                  value={customModel}
                  onChange={(e, { value }) => {
                    setCustomModel(value);
                  }}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      addCustomModel();
                      e.preventDefault();
                    }
                  }}
                />
              </div>
            )}
            {inputs.type !== 43 && fetchedModels.length > 0 && (
              <div style={{ marginBottom: '16px' }}>
                <div style={{ marginBottom: '8px', color: 'rgba(0,0,0,0.4)', fontSize: '12px' }}>
                  {t('channel.edit.labels.fetched_models', { count: fetchedModels.length })}
                </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
                  {fetchedModels.map((model) => (
                    <Label
                      key={model}
                      as='a'
                      onClick={() => {
                        if (!inputs.models.includes(model)) {
                          handleInputChange(null, {
                            name: 'models',
                            value: [...inputs.models, model],
                          });
                        }
                      }}
                      style={{
                        cursor: 'pointer',
                        backgroundColor: inputs.models.includes(model)
                          ? '#e8f5e9'
                          : '#f5f5f5',
                        border: inputs.models.includes(model)
                          ? '1px solid #4caf50'
                          : '1px solid #ddd',
                        color: inputs.models.includes(model)
                          ? '#2e7d32'
                          : '#333',
                      }}
                    >
                      {inputs.models.includes(model) && '✓ '}
                      {model}
                    </Label>
                  ))}
                </div>
              </div>
            )}
            {inputs.type !== 43 && fetchError && (
              <Message negative style={{ marginBottom: '12px' }}>
                <Message.Header>{t('channel.edit.labels.fetch_failed')}</Message.Header>
                <p>{fetchError}</p>
              </Message>
            )}
            {inputs.type !== 43 && (
              <>
                <Form.Field>
                  <label>{t('channel.edit.model_mapping')}</label>
                  {modelMappingPairs.length === 0 && (
                    <p style={{color: '#888', fontSize: '0.9em', marginBottom: 8}}>
                      暂无映射，在下发添加映射规则
                    </p>
                  )}
                  {modelMappingPairs.map((pair, idx) => (
                    <div key={idx} style={{
                      display: 'flex', alignItems: 'center', gap: 8,
                      marginBottom: 6, padding: '6px 10px',
                      background: '#f8f9fa', borderRadius: 6,
                      border: '1px solid #e0e0e0'
                    }}>
                      <code style={{flex: 1, color: '#2185d0'}}>{pair.from}</code>
                      <span style={{color: '#aaa'}}>→</span>
                      <code style={{flex: 1, color: '#21ba45'}}>{pair.to}</code>
                      <Button size='mini' negative
                        onClick={() => removeModelMapping(idx)}
                        style={{margin: 0, minWidth: 28, padding: '4px 8px'}}>✕</Button>
                    </div>
                  ))}
                  <div style={{display: 'flex', gap: 8, alignItems: 'center', marginTop: 6, flexWrap: 'wrap'}}>
                    <Dropdown
                      placeholder='源模型'
                      search
                      selection
                      fluid
                      options={inputs.models.map(m => ({key: m, text: m, value: m}))}
                      allowAdditions
                      additionLabel='自定义: '
                      value={mappingFrom}
                      onChange={(e, {value}) => setMappingFrom(value)}
                      style={{minWidth: 160, flex: '1 1 140px'}}
                    />
                    <span style={{color: '#aaa'}}>→</span>
                    <Dropdown
                      placeholder='目标模型'
                      search
                      selection
                      fluid
                      options={inputs.models.map(m => ({key: m, text: m, value: m}))}
                      allowAdditions
                      additionLabel='自定义: '
                      value={mappingTo}
                      onChange={(e, {value}) => setMappingTo(value)}
                      style={{minWidth: 160, flex: '1 1 140px'}}
                    />
                    <Button primary size='mini'
                      onClick={() => {
                        if (mappingFrom && mappingTo) {
                          addModelMapping(mappingFrom, mappingTo);
                          setMappingFrom('');
                          setMappingTo('');
                        }
                      }}
                      style={{margin: 0}}>添加</Button>
                  </div>
                </Form.Field>
                <Form.Field>
                  <Form.TextArea
                    label={t('channel.edit.system_prompt')}
                    placeholder={t('channel.edit.system_prompt_placeholder')}
                    name='system_prompt'
                    onChange={handleInputChange}
                    value={inputs.system_prompt}
                    style={{
                      minHeight: 150,
                      fontFamily: 'JetBrains Mono, Consolas',
                    }}
                    autoComplete='new-password'
                  />
                </Form.Field>
              </>
            )}
            {inputs.type === 33 && (
              <Form.Field>
                <Form.Input
                  label='Region'
                  name='region'
                  required
                  placeholder={t('channel.edit.aws_region_placeholder')}
                  onChange={handleConfigChange}
                  value={config.region}
                  autoComplete=''
                />
                <Form.Input
                  label='AK'
                  name='ak'
                  required
                  placeholder={t('channel.edit.aws_ak_placeholder')}
                  onChange={handleConfigChange}
                  value={config.ak}
                  autoComplete=''
                />
                <Form.Input
                  label='SK'
                  name='sk'
                  required
                  placeholder={t('channel.edit.aws_sk_placeholder')}
                  onChange={handleConfigChange}
                  value={config.sk}
                  autoComplete=''
                />
              </Form.Field>
            )}
            {inputs.type === 42 && (
              <Form.Field>
                <Form.Input
                  label='Region'
                  name='region'
                  required
                  placeholder={t('channel.edit.vertex_region_placeholder')}
                  onChange={handleConfigChange}
                  value={config.region}
                  autoComplete=''
                />
                <Form.Input
                  label={t('channel.edit.vertex_project_id')}
                  name='vertex_ai_project_id'
                  required
                  placeholder={t('channel.edit.vertex_project_id_placeholder')}
                  onChange={handleConfigChange}
                  value={config.vertex_ai_project_id}
                  autoComplete=''
                />
                <Form.Input
                  label={t('channel.edit.vertex_credentials')}
                  name='vertex_ai_adc'
                  required
                  placeholder={t('channel.edit.vertex_credentials_placeholder')}
                  onChange={handleConfigChange}
                  value={config.vertex_ai_adc}
                  autoComplete=''
                />
              </Form.Field>
            )}
            {inputs.type === 34 && (
              <Form.Input
                label={t('channel.edit.user_id')}
                name='user_id'
                required
                placeholder={t('channel.edit.user_id_placeholder')}
                onChange={handleConfigChange}
                value={config.user_id}
                autoComplete=''
              />
            )}
            {/* dyt-114: 上游协议出口开关。
                决定"网关 -> 上游"说什么协议，与客户端用什么入口协议无关。
                默认关闭，保持既有 chat 行为。 */}
            <Form.Group widths='equal'>
              <Form.Field>
                <Checkbox
                  toggle
                  label='使用 Responses API 上游（/v1/responses）'
                  name='use_responses_api'
                  checked={!!config.use_responses_api}
                  onChange={(e, { checked }) =>
                    handleConfigChange(e, { name: 'use_responses_api', value: !!checked })
                  }
                />
                <Label basic size='small' style={{ marginTop: '6px' }}>
                  仅适用于上游只提供 Responses 端点的场景
                </Label>
              </Form.Field>
              <Form.Field>
                <Checkbox
                  toggle
                  label='使用 Gemini Interactions 上游（/v1beta/interactions）'
                  name='use_interactions_api'
                  checked={!!config.use_interactions_api}
                  onChange={(e, { checked }) =>
                    handleConfigChange(e, { name: 'use_interactions_api', value: !!checked })
                  }
                />
                <Label basic size='small' style={{ marginTop: '6px' }}>
                  仅 Gemini 渠道；替代旧的 generateContent
                </Label>
              </Form.Field>
            </Form.Group>
            {inputs.type !== 33 &&
              inputs.type !== 42 &&
              (batch ? (
                <Form.Field>
                  <Form.TextArea
                    label={t('channel.edit.key')}
                    name='key'
                    required
                    placeholder={t('channel.edit.batch_placeholder')}
                    onChange={handleInputChange}
                    value={inputs.key}
                    style={{
                      minHeight: 150,
                      fontFamily: 'JetBrains Mono, Consolas',
                    }}
                    autoComplete='new-password'
                  />
                </Form.Field>
              ) : (
                <Form.Field>
                  <Form.Input
                    label={t('channel.edit.key')}
                    name='key'
                    required
                    placeholder={type2secretPrompt(inputs.type, t)}
                    onChange={handleInputChange}
                    value={inputs.key}
                    autoComplete='new-password'
                  />
                </Form.Field>
              ))}
            {inputs.type === 37 && (
              <Form.Field>
                <Form.Input
                  label='Account ID'
                  name='user_id'
                  required
                  placeholder={
                    '请输入 Account ID，例如：d8d7c61dbc334c32d3ced580e4bf42b4'
                  }
                  onChange={handleConfigChange}
                  value={config.user_id}
                  autoComplete=''
                />
              </Form.Field>
            )}
            {inputs.type !== 33 && !isEdit && (
              <Form.Checkbox
                checked={batch}
                label={t('channel.edit.batch')}
                name='batch'
                onChange={() => setBatch(!batch)}
              />
            )}
            {inputs.type !== 3 &&
              inputs.type !== 33 &&
              inputs.type !== 8 &&
                inputs.type !== 50 &&
              inputs.type !== 22 && (
                <Form.Field>
                  <Form.Input
                      label={t('channel.edit.proxy_url')}
                    name='base_url'
                      placeholder={t('channel.edit.proxy_url_placeholder')}
                    onChange={handleInputChange}
                    value={inputs.base_url}
                    autoComplete='new-password'
                  />
                </Form.Field>
              )}
            {inputs.type === 22 && (
              <Form.Field>
                <Form.Input
                  label='私有部署地址'
                  name='base_url'
                  placeholder={
                    '请输入私有部署地址，格式为：https://fastgpt.run/api/openapi'
                  }
                  onChange={handleInputChange}
                  value={inputs.base_url}
                  autoComplete='new-password'
                />
              </Form.Field>
            )}
            <Button onClick={handleCancel}>
              {t('channel.edit.buttons.cancel')}
            </Button>
            <Button
              type={isEdit ? 'button' : 'submit'}
              positive
              onClick={submit}
            >
              {t('channel.edit.buttons.submit')}
            </Button>
          </Form>
        </Card.Content>
      </Card>
    </div>
  );
};

export default EditChannel;
